DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def _check_base(base):
    if not isinstance(base, int) or isinstance(base, bool) or not 2 <= base <= 36:
        raise ValueError(f"base must be an integer from 2 to 36, got {base!r}")


def to_base(number, base):
    _check_base(base)
    if not isinstance(number, int) or isinstance(number, bool):
        raise ValueError(f"number must be an int, got {number!r}")
    if number == 0:
        return "0"
    sign = "-" if number < 0 else ""
    n = abs(number)
    out = []
    while n:
        n, r = divmod(n, base)
        out.append(DIGITS[r])
    return sign + "".join(reversed(out))


def from_base(text, base):
    _check_base(base)
    if not isinstance(text, str):
        raise ValueError(f"text must be a str, got {text!r}")
    body = text[1:] if text.startswith("-") else text
    if body == "":
        raise ValueError(f"no digits in {text!r}")
    valid = DIGITS[:base]
    value = 0
    for ch in body:
        # Only ASCII letters fold case; non-ASCII characters are never digits.
        folded = ch.lower() if ("A" <= ch <= "Z") else ch
        idx = valid.find(folded) if folded.isascii() else -1
        if idx < 0:
            raise ValueError(f"invalid digit {ch!r} for base {base}")
        value = value * base + idx
    return -value if text.startswith("-") else value
